function render() {
  const e = player.eye;
  camera.position.set(e.x, e.y, e.z);
  camera.rotation.y = player.yaw;
  camera.rotation.x = player.pitch;
  vmKick = Math.max(0, vmKick - 0.008);
  viewmodel.position.z = -0.55 + vmKick;
