// --- main loop ----------------------------------------------------------
let last = performance.now();
let acc = 0;
let frozen = false;
function loop(now) {
  if (frozen) return;
  requestAnimationFrame(loop);
  if (shotMode) {
    // Screenshot mode: render the frozen frame every tick, never advance the sim.
    render();
    updateHud();
    if (!window.__shotReady) window.__shotReady = true;
    return;
  }
  const dt = Math.min(0.1, (now - last) / 1000);
  last = now;
  acc += dt;
  let n = 0;
  while (acc >= STEP && n < 5) {
    step(STEP);
    acc -= STEP;
    n++;
  }
  render();
  updateHud();
}

function settle(steps) {
  for (let i = 0; i < steps; i++) step(STEP);
  render();
}

function paintTwiceThenReady() {
  render();
  updateHud();
  render();
  // __shotReady is set by the RAF loop once it has presented a frame.
}

// --- screenshot modes ---------------------------------------------------
function runShot(name) {
  hud.hideOverlay();
  input.forceLock();
  player.yaw = 0;
  player.pitch = 0;
  if (name === 'play') {
    rounds.round = 3;
    rounds.scoreEmber = 2;
