    aimAt(bots.aimPoint(3));
  } else if (name === 'end') {
    rounds.round = 6;
    rounds.scoreEmber = 3;
    rounds.scoreSlate = 2;
    rounds.money = 2200;
    rounds.phase = 'playing';
    rounds.bomb.planted = true;
    rounds.bomb.site = 'A';
    rounds.bomb.x = -14;
    rounds.bomb.z = -10;
    rounds.bomb.timer = 32;
    world.bombMesh.position.set(-14, 0, -10);
