              bot.heard = null;
              bot.state = 'patrol';
              bot.stateT = 0;
            }
          }
          if (bot.team === 'slate' && ctx.bombPlanted && ctx.bombPos) {
            const d = Math.hypot(bot.pos.x - ctx.bombPos.x, bot.pos.z - ctx.bombPos.z);
            if (d < 16) {
              bot.state = 'defuse';
              bot.defuseT = 0;
              bot.stateT = 0;
