          }
          bot.lastX = bot.pos.x;
          bot.lastZ = bot.pos.z;
          bot.stuckT = 0;
        }

        bot.mesh.position.copy(bot.pos);
        bot.mesh.rotation.y = bot.yaw;
        void tmp;
      }
    },
  };
